import assert from 'node:assert/strict';
const samples = JSON.parse(process.argv[2]);
const result = [];
for (const sample of samples) {
  const {sum} = await import('data:text/javascript;base64,' + Buffer.from(sample.source).toString('base64'));
  const actual = [sum(2,3), sum(-2,3)];
  assert.deepEqual(actual, sample.expected);
  result.push({mode:sample.mode, actual});
}
console.log(JSON.stringify(result));
